import{z as s,x as n,o as E,c as B,q as i,j as t,D as e,d as A,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"RegMix","description":"","frontmatter":{"title":"RegMix","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/regmix.md","filePath":"llm/regmix.md","lastUpdated":1791413859000}'),p={name:"llm/regmix.md"};function D(d,a,m,h,g,R){const r=n("Mermaid");return E(),B("div",null,[a[2]||(a[2]=i('<h1 id="regmix" tabindex="-1">RegMix <a class="header-anchor" href="#regmix" aria-label="Permalink to &quot;RegMix&quot;">​</a></h1><div class="epigraph"><p>把数据配比当成回归问题的自变量：在小模型上扫一批混合物，拟合损失面，再在面上求满足约束的配比，接到大模型。</p><footer>—— Liu 等，RegMix: Data Mixture as Regression for Language Model Pretraining</footer></div><p><a href="/llm/doremi">上一课</a>用代理模型上的 group DRO 求一组照顾最差桶的权重。DRO 每步都要训代理，桶一多、\\(w\\) 一切约束，实验图就不好画。本课不重讲超额损失。缺口是：能否用一批小规模训练的结果，把混合物到验证损失的映射拟合成可查询的面，从而少训几次、多回答「若代码再加 5% 会怎样」。Liu 等人的 RegMix 把配比写成回归。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/data-mixture-laws">配比定律</a> 希望 \\(w\\) 随规模可外推。DoReMi 给出的是一个稳健点，不是一张面：你很难问「在单纯形上沿某条边移动时损失怎么变」，除非再开一串 DRO。网格穷举 \\(k\\) 维单纯形又太贵。需要实验设计：用远少于穷举的配比点训小模型，用回归（线性、核、或带交互项）预测未见过的 \\(w\\) 的损失，再在预测面上做约束优化。</p><p><span class="marginnote">「单纯形」听起来吓人，其实就是「各桶比例加起来等于 1」的所有方案集合：两个桶是一条线段，三个桶是一张三角形，四个桶是四面体。所谓「顶点」，就是 100% 只喂某一桶的极端配比——恰恰是回归最没把握、又最需要知道答案的地方。</span></p>',6)),(E(),t(o,null,{default:e(()=>[l(r,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%83%B3%E7%9F%A5%E9%81%93%E9%85%8D%E6%AF%94%20w%20%E5%A6%82%E4%BD%95%E5%BD%B1%E5%93%8D%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%20GRID%5B%22%E7%BD%91%E6%A0%BC%E7%A9%B7%E4%B8%BE%3A%20k%20%E7%BB%B4%E5%8D%95%E7%BA%AF%E5%BD%A2%E5%85%A8%E6%89%AB%22%5D%0A%20%20GRID%20--%3E%20COST%5B%22%E6%A8%A1%E5%9E%8B%E6%95%B0%E9%9A%8F%20k%20%E6%8C%87%E6%95%B0%E6%B6%A8%2C%20%E9%A2%84%E7%AE%97%E7%88%86%E7%82%B8%22%5D%0A%20%20Q%20--%3E%20RM%5B%22RegMix%3A%20%E5%B0%91%E9%87%8F%E8%AE%BE%E8%AE%A1%E7%82%B9%E8%AE%AD%E5%B0%8F%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20RM%20--%3E%20FIT%5B%22%E6%8B%9F%E5%90%88%E5%93%8D%E5%BA%94%E9%9D%A2%20g(w)%22%5D%0A%20%20FIT%20--%3E%20QUERY%5B%22%E4%BB%BB%E6%84%8F%E5%8F%8D%E4%BA%8B%E5%AE%9E%E9%9A%8F%E6%9F%A5%E9%9A%8F%E7%AD%94%22%5D%0A%20%20QUERY%20--%3E%20RISK%5B%22%E8%AE%BE%E8%AE%A1%E7%82%B9%E6%8C%A4%E5%9C%A8%E5%9D%87%E5%8C%80%E5%8C%BA%2C%20%E9%A1%B6%E7%82%B9%E5%A4%96%E6%8E%A8%E4%B8%8D%E5%8F%AF%E4%BF%A1%22%5D%0A%20%20RISK%20--%3E%20FIX%5B%22%E5%90%91%E9%A1%B6%E7%82%B9%E9%99%84%E8%BF%91%E5%8A%A0%E5%AF%86%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p>回归的风险是外推。训练点若都挤在均匀配比附近，面在顶点（单桶）处不可信。DoReMi 的最差桶逻辑在顶点附近最敏感，RegMix 若没采到那些点，会画出过于乐观的网页独大解。</p><h3 id="响应变量选错则面无用" tabindex="-1">响应变量选错则面无用 <a class="header-anchor" href="#响应变量选错则面无用" aria-label="Permalink to &quot;响应变量选错则面无用&quot;">​</a></h3><p>用网页验证损失当 \\(y\\)，回归会推荐多喂网页。应用与 DoReMi 相同的多探针：把 \\(y\\) 做成向量，或做成加权标量并报告帕累托。RegMix 的工程价值在于一次设计回答多个反事实，而不是替换掉探针纪律。</p><p><span class="marginnote">小模型的损失面平移到大模型时，最优 \\(w\\) 可能移动。RegMix 原文强调小到大的迁移；实践仍应在目标尺度做少量确认点，与 DoReMi 同一条警告。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定 \\(k\\) 个桶与单纯形上的设计（单纯形格点、Dirichlet 抽样、或把人工配比当作中心再扰动）。每个设计点训一个固定 FLOPs 的小模型，记录各探针损失。拟合 \\(y\\approx g(w)\\)，在 \\(w\\in\\Delta^{k-1}\\) 且盒约束上最小化 \\(g\\)，得到推荐 \\(w^\\star\\)。用一两个未参与拟合的设计点做持出检验；误差大就加密采样或降低多项式阶数。</p><p><span class="marginnote">省多少可以算笔账：5 个桶、每桶扫 4 档的网格要 \\(4^5=1024\\) 次小模型训练；RegMix 用几十个 Dirichlet 随机配比点拟一个二次响应面，就能随口问出「代码加 5%、网页减 5% 会怎样」——把上千次实验压成几十次。</span></p><p>与 DoReMi 的分工：RegMix 适合「想看面、想做预算问答」；DRO 适合「明确要压最差桶」。可以先用 RegMix 缩小区域，再在该区域跑一次 DRO 精修。不要同时把两套 \\(w\\) 写进同一加载器。</p><h3 id="设计点必须是真实加载器" tabindex="-1">设计点必须是真实加载器 <a class="header-anchor" href="#设计点必须是真实加载器" aria-label="Permalink to &quot;设计点必须是真实加载器&quot;">​</a></h3><p>每个设计点的 \\(w\\) 要落实到与大模型相同的切分、相同的去重后集合。否则回归拟合的是另一套离散测度。fertility 高的桶在「按 token 的 \\(w\\)」下已经少句，面里会自动体现——前提是 \\(w\\) 的定义始终是 token 份额。</p><p><span class="marginnote">回归系数可以当诊断：某桶的主效应为负，说明加它普遍降损失；交互项为正，说明它与另一桶互相抢信号。这比只交出一个 \\(w^\\star\\) 更有用。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>在固定架构与步数下，混合物 \\(w\\) 改变梯度期望，从而改变收敛到的参数，再改变探针损失。若该映射平滑，少量点就能拟合。不平滑的来源：某桶含污染或重复，权重一过阈值模型开始背评测；或某能力只在足够比例后才出现，面呈平台后陡降。此时应分段拟合或加设计点，而不是提高多项式阶数去振荡。</p>',13)),(E(),t(o,null,{default:e(()=>[l(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E5%8D%95%E7%BA%AF%E5%BD%A2%E8%AE%BE%E8%AE%A1%E7%82%B9%22%5D%20--%3E%20S%5B%22%E5%B0%8F%E6%A8%A1%E5%9E%8B%E5%9B%BA%E5%AE%9A%20FLOPs%22%5D%0A%20%20S%20--%3E%20Y%5B%22%E5%A4%9A%E6%8E%A2%E9%92%88%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20Y%20--%3E%20G%5B%22%E6%8B%9F%E5%90%88%20g(w)%22%5D%0A%20%20G%20--%3E%20OPT%5B%22%E7%BA%A6%E6%9D%9F%E4%B8%8B%E6%B1%82%20w%20%E6%98%9F%22%5D%0A%20%20OPT%20--%3E%20BIG%5B%22%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%A1%AE%E8%AE%A4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>RegMix 仍是桶级方法，不选文档。桶内若质量双峰，面会被平均值糊掉。规模迁移没有理论保证，只是经验上「比随机猜 \\(w\\) 好」。下一课把分辨率从桶降到文档，用影响函数问「这一份对目标探针的贡献」，计算更贵，换来的是配比无法表达的细选择。</p><p><span class="marginnote">常见误区：把响应面当万能公式，外推到没采样过的区域。回归只在设计点附近可信；桶内质量双峰时，面给出的是「平均行为」，会掩盖一半极好、一半极坏的真相。所以面上的最优 \\(w^\\star\\) 必须靠持出点和大模型确认来背书，不能直接上生产。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲 DRO；只补混合物到损失的可查询回归面。</li><li>设计点要覆盖单纯形，尤其接近单桶的区域，否则外推虚假。</li><li>响应必须是多探针；持出检验与大模型确认不可省。</li><li>可与 DoReMi 串联：先看面，再在区域内 DRO。</li><li>出处：Liu et al., <em>RegMix</em>；对照 Xie et al., DoReMi, NeurIPS 2023。</li></ul>',5))])}const u=s(p,[["render",D]]);export{x as __pageData,u as default};
